class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        dp = set()
        for v in nums:
            new = set(dp)
            if v <= limit:
                new.add((v, v))
                new.add((-v, v))
            for (d, p) in dp:
                pv = p * v
                if pv <= limit:
                    new.add((d + v, pv))
                    new.add((d - v, pv))
            dp = new
        best = -1
        for (d, p) in dp:
            if d == k and p > best:
                best = p
        return best

