class Solution {
public:
    int maxProduct(vector<int>& nums, int k, int limit) {
        set<pair<int,int>> dp;
        for (int v : nums) {
            auto nw = dp;
            if (v <= limit) { nw.insert({v, v}); nw.insert({-v, v}); }
            for (auto& [d, p] : dp) {
                long long pv = (long long)p * v;
                if (pv <= limit) {
                    nw.insert({d + v, (int)pv});
                    nw.insert({d - v, (int)pv});
                }
            }
            dp = move(nw);
        }
        int best = -1;
        for (auto& [d, p] : dp)
            if (d == k && p > best) best = p;
        return best;
    }
};

