class Solution {
    public int maxProduct(int[] nums, int k, int limit) {
        Set<Long> dp = new HashSet<>();
        for (int v : nums) {
            Set<Long> nw = new HashSet<>(dp);
            if (v <= limit) { nw.add(key(v, v)); nw.add(key(-v, v)); }
            for (Long st : dp) {
                int d = (int)(st >> 20), p = (int)(st & 0xFFFFF);
                long pv = (long) p * v;
                if (pv <= limit) {
                    nw.add(key(d + v, (int) pv));
                    nw.add(key(d - v, (int) pv));
                }
            }
            dp = nw;
        }
        int best = -1;
        for (Long st : dp) {
            int d = (int)(st >> 20), p = (int)(st & 0xFFFFF);
            if (d == k && p > best) best = p;
        }
        return best;
    }
    private long key(int d, int p) { return (((long)(d + (1 << 19))) << 20) | p; }
}

