var maxProduct = function(nums, k, limit) {
    let dp = new Map();
    const key = (d, p) => d + ',' + p;
    for (const v of nums) {
        const nw = new Map(dp);
        if (v <= limit) { nw.set(key(v, v), true); nw.set(key(-v, v), true); }
        for (const kk of dp.keys()) {
            const [d, p] = kk.split(',').map(Number);
            const pv = p * v;
            if (pv <= limit) {
                nw.set(key(d + v, pv), true);
                nw.set(key(d - v, pv), true);
            }
        }
        dp = nw;
    }
    let best = -1;
    for (const kk of dp.keys()) {
        const [d, p] = kk.split(',').map(Number);
        if (d === k && p > best) best = p;
    }
    return best;
};
